-- 2026-11-02_별칭_0906_보충.sql  (필수, 데이터 수정)
--
-- corpus.item_alias 를 두 가지로 고친다.
--   1) 사업명 '초격차' 를 정식 사업명 '초격차 스타트업 프로젝트' 으로 바꾼다.
--   2) 2026-09-06 에 넣은 별칭 98건 중 운영에 빠진 26건을 넣는다.
--
-- 왜
--   1) 서버는 판정 전에 사업명을 corpus.programs 의 정식 이름으로 바꾸고(server/catalog._사업명_표준화),
--      rule_lookup.비목후보_조회 는 item_alias 를 `사업명 = 정식 이름 OR 사업명 IS NULL` 로 찾는다.
--      그래서 사업명이 '초격차' 로 저장된 별칭은 정확 조회에 한 번도 걸리지 않았다. 다른 표(rules·
--      precedence_rules·check_items·chunks)는 모두 정식 이름을 쓴다.
--   2) 9/6 별칭 98건(출처 규정발췌_20260906_*)은 로컬에는 모두 있지만 운영(당시 GCP, 10/27 덤프로 이관)에는
--      72건만 들어갔다. 빠진 행은 로컬 alias_id 229~273 구간에 있던 행이다(운영에서 같은 번호를 다른 행이
--      먼저 차지했다). 9/6 인수인계 기록의 의도 상태는 326행이다.
--   넣는 행과 이름을 바꾸는 초격차 행은 모두 규정 원문과 대조했다(2026-11-02, 검증 결과는 PR 본문).
--   원문발췌는 같은 doc_id 의 active 청크 텍스트에 그대로 있는 문장이다(청크 텍스트는 운영·로컬이 같다).
--   9/6 별칭 98건은 임베딩이 없다. 이 파일도 임베딩을 넣지 않는다(벡터 조회에는 걸리지 않는다).
--
-- 멱등: 다시 실행해도 같은 상태가 된다. 이름을 바꾸는 행의 변경 전 값은 backup_dq_20261102.item_alias_초격차 에 남긴다.
-- 실행 (운영, deploy/ncp): ./backup.sh 후
--   docker compose exec -T db psql -U postgres -d suddoe -X -v ON_ERROR_STOP=1 -f - < ../../db/migrations/2026-11-02_별칭_0906_보충.sql

\set ON_ERROR_STOP on
BEGIN;
CREATE SCHEMA IF NOT EXISTS backup_dq_20261102;
REVOKE ALL ON SCHEMA backup_dq_20261102 FROM PUBLIC;
CREATE TABLE IF NOT EXISTS backup_dq_20261102."item_alias_초격차" (LIKE corpus.item_alias);
INSERT INTO backup_dq_20261102."item_alias_초격차"
SELECT a.* FROM corpus.item_alias a
 WHERE a."사업명" = '초격차'
   AND NOT EXISTS (SELECT 1 FROM backup_dq_20261102."item_alias_초격차" b WHERE b.alias_id = a.alias_id);

-- 1) 사업명 정식 이름으로
UPDATE corpus.item_alias SET "사업명" = '초격차 스타트업 프로젝트' WHERE "사업명" = '초격차';

-- 2) 빠진 행 넣기. 이미 있으면(로컬) 비목이 같을 때만 근거 칼럼을 채운다
