-- 3) 이름을 바꾼 기존 초격차 행의 근거 칼럼 채우기
UPDATE corpus.item_alias a
   SET doc_id = v.doc_id, "조번호" = v."조번호", "원문발췌" = v."원문발췌"
  FROM (VALUES
('일반건강진단비용', '인건비', '초격차 스타트업 프로젝트 세부관리기준(제10차)', '참고2', '· 인건비를 지출하는 소속 직원에 한하여 산업안전보건법 제129조에 따른 일반건강진단 비용 집행 가능 단, 일반건강진단 외 추가건강진단 비용은 사업비로 집행 불가'),
