('장비 수리비', '지급수수료', '초격차 스타트업 프로젝트 세부관리기준(제10차)', '참고2', '• 장비 수리비:거래명세서, 견적서(신품 구매 견적 포함), 검수조서(증빙사진 포함)'),
('전자화폐', '광고선전비', '초격차 스타트업 프로젝트 세부관리기준(제10차)', '참고2', '· 협약기간 이후 잔여금액 또는 이월하여 사용할 수 있는 전자화폐(온라인 광고, 문자 등 충전‧차감 방식 등)의 경우 협약기간 내 완료된 실소요 비용만 집행 가능')
  ) AS v("품목", "비목", doc_id, "조번호", "원문발췌")
 WHERE a."품목" = v."품목" AND a."비목" = v."비목" AND a."사업명" = '초격차 스타트업 프로젝트' AND a."원문발췌" IS NULL;

DO $$
DECLARE
  n_전체 int; n_근거 int; n_청크 int;
BEGIN
  IF EXISTS (SELECT 1 FROM corpus.item_alias WHERE "사업명" = '초격차') THEN
    RAISE EXCEPTION '사업명 초격차 별칭이 남아 있다';
  END IF;
  IF EXISTS (SELECT 1 FROM corpus.item_alias a WHERE a."사업명" IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM corpus.programs p WHERE p."사업명" = a."사업명")) THEN
    RAISE EXCEPTION 'corpus.programs 에 없는 사업명을 가진 별칭이 있다';
  END IF;
  -- 검증한 35행이 같은 비목으로 있고, 근거 칼럼이 검증값과 같고, 원문발췌가 active 청크에 그대로 있는지
  SELECT count(*), count(*) FILTER (WHERE a."원문발췌" = v."원문발췌" AND a.doc_id = v.doc_id),
         count(*) FILTER (WHERE EXISTS (SELECT 1 FROM corpus.chunks c WHERE c.status = 'active' AND c.doc_id = v.doc_id
                                          AND position(v."원문발췌" in c.text) > 0))
    INTO n_전체, n_근거, n_청크
    FROM (VALUES
('회계감사비', '지급수수료', '창업중심대학', '창업중심대학 세부관리기준2025년 개정', '| 지급수수료 | 지급수수료 | 일반수용비 | 기술이전비, 학회 및 세미나 참가비, 전시회(박람회) 참가비, 시험‧인증비, 멘토링비, 운반비, 보험료, 회계감사비, 법인 설립비(온라인법인설립시스템 활용 시), 기술 보호비, 기계 장치 수리비 |'),
('세무기장료', '지급수수료', '창업중심대학', '창업중심대학 세부관리기준2025년 개정', '10) 세무기장료 : 창업기업의 협약기간 동안의 세무기장료(월별 청구건 또는 협약기간 동안의 세무기장료 후 지급) ※ 세무기장료 유의사항 - 연 세무기장료 선지급 또는 창업기업 우선집행 후 창업기업계좌로 대체불가(세무 사무소 등에 직접 입금)'),
('법인설립비', '지급수수료', '창업중심대학', '창업중심대학 세부관리기준2025년 개정', '| 지급수수료 | 지급수수료 | 일반수용비 | 기술이전비, 학회 및 세미나 참가비, 전시회(박람회) 참가비, 시험‧인증비, 멘토링비, 운반비, 보험료, 회계감사비, 법인 설립비(온라인법인설립시스템 활용 시), 기술 보호비, 기계 장치 수리비 |'),
('기술보호비', '지급수수료', '창업중심대학', '창업중심대학 세부관리기준2025년 개정', '| 지급수수료 | 지급수수료 | 일반수용비 | 기술이전비, 학회 및 세미나 참가비, 전시회(박람회) 참가비, 시험‧인증비, 멘토링비, 운반비, 보험료, 회계감사비, 법인 설립비(온라인법인설립시스템 활용 시), 기술 보호비, 기계 장치 수리비 |'),
('규제애로 해소 법률컨설팅비', '지급수수료', '창업중심대학', '창업중심대학 세부관리기준2025년 개정', '14) 규제애로 해소 법률컨설팅비: 창업아이템과 직접적인 관련이 있는 규제의 법률 검 토 및 개선방안 마련 등을 위한 법률컨설팅 진행 후 지급 비용 집행'),
('사무실임차료', '지급수수료', '창업중심대학', '창업중심대학 세부관리기준2025년 개정', '| 지급수수료 | 지급수수료 | 일반수용비 | 기술이전비, 학회 및 세미나 참가비, 전시회(박람회) 참가비, 시험‧인증비, 멘토링비, 운반비, 보험료, 회계감사비, 법인 설립비(온라인법인설립시스템 활용 시), 기술 보호비, 기계 장치 수리비 |
