('전자화폐', '광고선전비', '초격차 스타트업 프로젝트', '초격차 스타트업 프로젝트 세부관리기준(제10차)', '· 협약기간 이후 잔여금액 또는 이월하여 사용할 수 있는 전자화폐(온라인 광고, 문자 등 충전‧차감 방식 등)의 경우 협약기간 내 완료된 실소요 비용만 집행 가능')
    ) AS v("품목", "비목", "사업명", doc_id, "원문발췌")
    JOIN corpus.item_alias a ON a."품목" = v."품목" AND a."사업명" = v."사업명" AND a."비목" = v."비목";
  IF n_전체 <> 35 OR n_근거 <> 35 OR n_청크 <> 35 THEN
    RAISE EXCEPTION '검증 행 확인 실패: 있음 %, 근거 일치 %, 청크 일치 % (기대 35)', n_전체, n_근거, n_청크;
  END IF;
  RAISE NOTICE '별칭 0906 보충: 확인 통과 (검증 행 %)', n_전체;
END $$;
COMMIT;
